INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Tarta de naranja, almendras y chispas de chocolate' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 4 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Almendras molidas|Eritritol|Levadura química (polvo de hornear)|Chocolate con alto % de cacao' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 210.0;
INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Tortitas crocantes de patatas' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 2 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Patatas|Aceite de oliva virgen extra (AOVE)' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 210.0;
INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Tostones (patacones) horneados con kétchup saludable' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 5 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Plátano macho|Agua|Aceite de oliva virgen extra (AOVE)|Sirope de dátil|Tomate concentrado' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 1305.0;
INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Tots de brócoli' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 12 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Brócoli|Cebolla blanca|Perejil|Queso cheddar|Harina de almendras|Aceite de oliva virgen extra (AOVE)|Sirope de dátil|Tomate concentrado|Agua|Tahini|Sal|Zumo de limón' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 363.5;
INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Trucha con jamón y picada' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 5 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Aceite de oliva virgen extra (AOVE)|Perejil|Azafrán|Avellanas|Sal' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 82.0;
INSERT INTO _libro (id) SELECT r.id FROM recipes r WHERE r.name = 'Wok de setas' AND (SELECT count(*) FROM recipe_ingredients WHERE recipe_id = r.id) = 8 AND ifnull((SELECT group_concat(food, '|') FROM (SELECT food FROM recipe_ingredients WHERE recipe_id = r.id ORDER BY position)), '') = 'Setas variadas|Cebolla blanca|Jengibre fresco|Agua|Almidón de maíz (maicena)|Aceite de oliva virgen extra (AOVE)|Cebollino|Semillas de sésamo' AND (SELECT round(total(quantity), 3) FROM recipe_ingredients WHERE recipe_id = r.id) = 600.0;
