CREATE TABLE _libro (id INTEGER PRIMARY KEY);
DELETE FROM recipe_ingredients WHERE recipe_id IN (SELECT id FROM _libro);
DROP TABLE _libro;
UPDATE recipe_ingredients SET food_id = (SELECT id FROM foods WHERE foods.name = recipe_ingredients.food) WHERE food_id IS NULL AND food IN (SELECT name FROM foods);
